import{_ as t,o as n,c as a,a0 as s}from"./chunks/framework.DW5bL-_G.js";const h=JSON.parse('{"title":"Introduction","description":"EW Color Picker is an event-driven, plugin-based color picker. Learn what the core does and how the 13 packages fit together.","frontmatter":{"title":"Introduction","description":"EW Color Picker is an event-driven, plugin-based color picker. Learn what the core does and how the 13 packages fit together."},"headers":[],"relativePath":"en/guide/index.md","filePath":"en/guide/index.md"}'),o={name:"en/guide/index.md"};function r(i,e,l,d,c,p){return n(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>EW Color Picker is a modern color picker built around two ideas:</p><ol><li><strong>Event-driven</strong> — every action becomes an event (<code>change</code>, <code>sure</code>, <code>clear</code>, <code>toggle</code>, <code>mode-change</code>, <code>options-update</code>, <code>destroy</code>).</li><li><strong>Plugin-based</strong> — the core owns color state and mount points; every piece of UI is a plugin.</li></ol><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Core (@ew-color-picker/core)</span></span>
<span class="line"><span>├─ color state: currentColor + hsvaColor</span></span>
<span class="line"><span>├─ event bus: on / once / off / trigger / emit</span></span>
<span class="line"><span>├─ mount points: root + panelContainer</span></span>
<span class="line"><span>└─ plugins: can be registered, replaced, or extended</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="why-a-plugin-architecture" tabindex="-1">Why a plugin architecture? <a class="header-anchor" href="#why-a-plugin-architecture" aria-label="Permalink to &quot;Why a plugin architecture?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Benefit</th><th>What it means</th></tr></thead><tbody><tr><td>Small bundles</td><td>Install only the plugins you use</td></tr><tr><td>Replaceable UI</td><td>Swap the panel, input, or buttons for your own implementation</td></tr><tr><td>Testable</td><td>Each plugin can be tested in isolation</td></tr><tr><td>Extensible</td><td>Add features without touching the core</td></tr></tbody></table><h2 id="the-13-packages" tabindex="-1">The 13 packages <a class="header-anchor" href="#the-13-packages" aria-label="Permalink to &quot;The 13 packages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>@ew-color-picker/core</code></td><td>Color state, event bus, mount points, plugin registry</td></tr><tr><td><code>@ew-color-picker/utils</code></td><td>DOM/color/animation helpers, <code>EventEmitter</code>, <code>Console</code> plugin</td></tr><tr><td><code>@ew-color-picker/style</code></td><td>CSS (<code>index.css</code> + <code>input-number.css</code>)</td></tr><tr><td><code>@ew-color-picker/ew-color-picker</code></td><td>All-in-one bundle: registers all plugins and re-exports the core</td></tr><tr><td><code>@ew-color-picker/box</code></td><td>Trigger swatch that opens/closes the panel</td></tr><tr><td><code>@ew-color-picker/panel</code></td><td>Saturation/value 2D panel</td></tr><tr><td><code>@ew-color-picker/hue</code></td><td>Hue slider (0–360°)</td></tr><tr><td><code>@ew-color-picker/alpha</code></td><td>Alpha slider (0–1)</td></tr><tr><td><code>@ew-color-picker/input</code></td><td>Text color input with validation</td></tr><tr><td><code>@ew-color-picker/input-number</code></td><td>Numeric input component + plugin</td></tr><tr><td><code>@ew-color-picker/button</code></td><td>Clear / Sure buttons</td></tr><tr><td><code>@ew-color-picker/predefine</code></td><td>Predefined color swatches</td></tr><tr><td><code>@ew-color-picker/color-mode</code></td><td>Hex / RGB / HSL mode switching</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User interaction (Box / Panel / Hue / Alpha / Input / Predefine / Button)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>   core.setColor(color)        ← the only way to change color</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├─► emit(&#39;change&#39;, color)</span></span>
<span class="line"><span>        │     ├─ Panel   sync background + cursor</span></span>
<span class="line"><span>        │     ├─ Hue     sync thumb</span></span>
<span class="line"><span>        │     ├─ Alpha   sync thumb</span></span>
<span class="line"><span>        │     ├─ Input   sync text</span></span>
<span class="line"><span>        │     ├─ ColorMode sync R/G/B or H/S/L inputs</span></span>
<span class="line"><span>        │     └─ Box     sync background + icon color</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        └─► options.changeColor(color)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><h2 id="design-principles" tabindex="-1">Design principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design principles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Principle</th><th>Detail</th></tr></thead><tbody><tr><td>Single source of truth</td><td>Only <code>core.setColor()</code> changes color; plugins never call each other directly</td></tr><tr><td>Instance isolation</td><td>Each instance has its own event bus, DOM and plugin instances</td></tr><tr><td>No global pollution</td><td>CSS is scoped by class names; the only global is the UMD <code>window.ewColorPicker</code></td></tr><tr><td>Progressive disclosure</td><td>Defaults work out of the box; every plugin exposes options and methods when you need them</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./installation">Installation</a></li><li><a href="./getting-started">Quick start</a></li><li><a href="./concepts">Core concepts</a></li><li><a href="./plugin-dev">Write a plugin</a></li></ul>`,14)])])}const b=t(o,[["render",r]]);export{h as __pageData,b as default};
